def solve(n: int, array: list[int]) -> QuantumCircuit:
    qc = QuantumCircuit(n)
    for qubit in range(n):
        qc.x(qubit)
        for element in array:
            if element % 2 == 0:
                qc.cx(qubit, qubit)
            else:
                qc.cx(qubit, n + qubit)
    qc.x(qubit)
    return qc

