let oracle = new Oracled({
    target: 0, 
    circuit: function (qc) {
        // phase kickback
        qc.ccx(1, 0, 0);
        qc.x(0);
        qc.ccx(1, 0, 0);
        qc.x(0);

        // addition
        qc.ccx(0, 0, 1);
        qc.ccx(0, 1, 0);
        qc.t(0);
        qc.ccx(0, 1, 0);
        qc.ccx(0, 0, 1);
    }
});
oracle.addRegisters(3, [3]);
</script>

